/* 阿X／小X／老X 這種暱稱：第二字不能是這些常見字，否則「老兒」「小聲」會被當成人名。 */
const PREFIX_BAD = new Set('兒人太師闆頭家時心聲便的了是在有大小多少東西樣麼候邊面前後上下內外'.split(''));

/* 名字前面必須是這些字之一（或字串開頭），避免把長詞的尾巴當成名字
   —— 例如「馬榮高聲罵道」不該抓出「高聲罵」。 */
const NAME_BOUND = new Set(('，。！？：；、,.!?:;」』】）)…—「『【（( \n\t' +
  '的與和跟對向從把被讓見問看聽給替為同是在有把將並而則但卻就也都很更最又再還只才便').split(''));

/* 「著」「了」「完」是動詞補語，後面接名字很常見（「對著小陳說道」「看見阿興走來」），
   不當邊界就會整段名字漏抓。 */
function boundaryOK(prev) { return prev === '' || NAME_BOUND.has(prev) || '著了完過起'.indexOf(prev) >= 0; }

/* 這些字可以是「名字前面」的字，但不能是名字的開頭 ——
   否則「向狄公道」會被抓成「向狄公」（介詞被吞進名字）。 */
const NOT_NAME_START = new Set(('向對跟和與從把被讓給替為同朝將並而則但卻就也都很更最又再還只才便是在有' +
  '的說道問答喊叫看聽想見知要能可是的了').split(''));

function looksLikeName(s) {
  if (!/^[\u4e00-\u9fff]{2,4}$/.test(s)) return false;
  if (NOT_NAME.has(s) || ROLE_WORDS.indexOf(s) >= 0) return false;
  if (NOT_NAME_START.has(s[0])) return false;
  for (const p of SURNAMES2) if (s.indexOf(p) === 0) return true;
  if (s.length === 2) {
    if (NAME_PREFIX.has(s[0])) return !PREFIX_BAD.has(s[1]);
    return SURNAMES.has(s[0]);
  }
  if (s.length === 3) return SURNAMES.has(s[0]);
  return false;
}

