const HARD_BOUND = new Set(('，。！？：；、,.!?:;」』】）)…—「『【（( \n\t\r　').split(''));

/* 放寬判定的守門員：台灣短篇常寫「不帶姓的名字」（阿明／德山／春姐），
   姓氏規則抓不到，但它們幾乎都出現在「標點後面 + 對白動詞前」這個位置。
   代名詞、數詞、疑問詞一律排除，避免「向他說道」「兩人說道」被當成人名。 */
const NAME_BAD_CHAR = new Set(('他她它我你您其們誰何什怎幾兩三四五六七八九十百千').split(''));
/* 名字不會用這些字結尾（「她的」「不知」…），拿來擋句首統計的雜訊。 */
const NAME_BAD_TAIL = new Set(('的了著是在有和與也都就便又很太更最把將被給對向跟同從而且則但卻嗎呢吧啊哦喔呀嘛個之於為以並'.split('')));
/* 實物結尾的字：「小飛機」「老照片」這種會被「小／老／阿」前綴誤收成人名。 */
const THING_TAIL = new Set(('機車船房門窗槍刀劍衣鞋帽紙筆錢藥杯碗袋箱盤桌椅床燈鏡錶'.split('')));
/* 動詞／方位結尾：「狄公道」「狄公聽」「且看下」都是「名字＋動詞」被整串抓走。 */
const VERB_TAIL = new Set(('道說問答看聽見想走去來拿放坐站轉低抬笑哭喊叫罵喝望瞪搖點打抓推拉開關停起落升降下上中內外前後間過完了著'.split('')));
function canBeBareName(s) {
  if (s.length < 2 || s.length > 3) return false;
  if (NOT_NAME.has(s) || ADV_ISH.has(s)) return false;
  if (ROLE_WORDS.indexOf(s) >= 0 || FAMILY_WORDS.has(s) || NAME_TITLES.indexOf(s) >= 0) return false;
  if (NOT_NAME_START.has(s[0]) || HARD_BOUND.has(s[0])) return false;
  if (NAME_BAD_TAIL.has(s[s.length - 1]) || THING_TAIL.has(s[s.length - 1])
    || VERB_TAIL.has(s[s.length - 1])) return false;
  for (const c of s) if (NAME_BAD_CHAR.has(c)) return false;
  return true;
}

