/* 從每個動詞往前找 2–4 字，由短到長取第一個通過檢查的。
   由短到長很重要：貪婪匹配會把「馬榮高聲罵道」抓成「高聲罵」。 */
function extractPersons(text, limit) {
  const cnt = new Map();
  const intro = new Set();          /* 「我叫X」句型抓到的名字＝敘述者候選 */
  const loose = new Set();          /* 靠放寬規則進來的名字，最後要用出現次數過濾 */
  const bump = n => cnt.set(n, (cnt.get(n) || 0) + 1);
  for (const v of SPEAK_VERBS.concat(MOVE_VERBS)) {
    let idx = -1;
    while ((idx = text.indexOf(v, idx + 1)) >= 0) {
      for (let len = 2; len <= 4; len++) {
        const start = idx - len;
        if (start < 0) break;
        const cand = text.slice(start, idx);
        if (!/^[\u4e00-\u9fff]+$/.test(cand)) break;
        if (!boundaryOK(start > 0 ? text[start - 1] : '')) break;
        if (looksLikeName(cand)) { bump(cand); break; }
        /* 放寬：緊接在標點後面、又掛在對白動詞前，就是很強的人名證據
           （「，阿明說道」）——姓氏規則抓不到不帶姓的名字。 */
        if (len <= 3 && canBeBareName(cand)
          && (start === 0 || HARD_BOUND.has(text[start - 1]))) { bump(cand); loose.add(cand); break; }
      }
    }
  }
  /* ② 名字與動詞之間夾著副詞：「名字＋副詞＋動詞」如「阿明安慰地說著」
     —— 不處理的話，「不帶姓的名字」寫法的作品主角會整個漏掉。
     副詞尾剝掉之後才找名字；剝不掉（沒有副詞）就交給 ① 的規則。 */
  for (const v of SPEAK_VERBS.concat(MOVE_VERBS)) {
    let idx = -1;
    while ((idx = text.indexOf(v, idx + 1)) >= 0) {
      const start0 = Math.max(0, idx - 12);
      const win = text.slice(start0, idx);
      const cut = win.replace(ADV_TAIL, '');
      if (cut === win || !cut) continue;
      const isDi = /地$/.test(win);          /* 「…地」結尾 → 允許較寬鬆的判定 */
      for (let len = 2; len <= 4; len++) {
        const cand = cut.slice(-len);
        if (cand.length !== len) break;
        if (!/^[\u4e00-\u9fff]+$/.test(cand)) continue;   /* 含引號／換行的一律不算（會產生「」正」這種垃圾） */
        const st = start0 + cut.length - len;
        if (st > 0 && !boundaryOK(text[st - 1])) break;
        if (looksLikeName(cand)) { bump(cand); break; }
        /* 寬鬆判定：「…地」句型（「阿明安慰地說著」）或標點開頭的名字 */
        if (len <= 3 && (isDi || st === 0 || HARD_BOUND.has(text[st - 1])) && canBeBareName(cand)) {
          bump(cand); loose.add(cand); break;
        }
      }
    }
  }

  /* 自我介紹句：「我叫X」——第一人稱小說這樣介紹主角，沒有「說道」可抓。 */
  for (const v of ['我叫', '我是', '名字叫', '叫作']) {
    let idx = -1;
    while ((idx = text.indexOf(v, idx + 1)) >= 0) {
      const s = idx + v.length;
      for (let len = 4; len >= 2; len--) {
        const cand = text.slice(s, s + len);
        if (!/^[\u4e00-\u9fff]+$/.test(cand) || cand.length !== len) continue;
        if (tailOK(text[s + len] || '')) { if (looksLikeName(cand)) { bump(cand); intro.add(cand); break; } }
      }
    }
  }
  /* 姓＋職業：「林刑警」「張醫生」「李老闆」——台灣小說最常見的寫法。
     名字只有一個姓加職業詞（總長 2-4 字），上面的 2-3 字規則抓不到
     （它往前要 2 字以上，前面只有一個姓就不夠）。 */
  const ALLOW_BEFORE = new Set(['和', '跟', '與', '同', '向', '對', '找', '問', '叫', '要', '請', '帶']);
  for (const r of ROLE_WORDS) {
    if (r.length < 2) continue;
    let idx = -1;
    while ((idx = text.indexOf(r, idx + 1)) >= 0) {
      const s = idx - 1;
      if (s < 0) continue;
      if (!SURNAMES.has(text[s])) continue;
      if (s > 0) { const prev = text[s - 1]; if (!boundaryOK(prev) && !ALLOW_BEFORE.has(prev)) continue; }
      const full = text[s] + r;
      if (NOT_NAME.has(full)) continue;
      bump(full);
    }
  }

  /* 名字＋職稱：「林啟明探長」——偵探小說指名道姓最常見的寫法。 */
  for (const t of NAME_TITLES) {
    let idx = -1;
    while ((idx = text.indexOf(t, idx + 1)) >= 0) {
      for (let len = 3; len >= 2; len--) {
        const start = idx - len;
        if (start < 0) continue;
        const cand = text.slice(start, idx);
        if (!/^[\u4e00-\u9fff]+$/.test(cand)) continue;
        if (start > 0 && !boundaryOK(text[start - 1])) break;
        if (looksLikeName(cand)) { bump(cand); break; }
      }
    }
  }
  /* ③ 不帶姓的名字（「正祥」「銘山」「英姐」）：姓氏規則抓不到，
     但它們會在句首反覆出現。統計「標點後開頭」的 2-3 字詞，出現夠多次
     就當名字 —— 連接詞／時間詞先擋掉（否則「於是」「忽然」會變人名）。 */
  const clause = new Map();
  for (let i = 0; i < text.length; i++) {
    if (i > 0 && !HARD_BOUND.has(text[i - 1])) continue;
    for (let len = 3; len >= 2; len--) {
      const cand = text.slice(i, i + len);
      if (cand.length !== len || !/^[\u4e00-\u9fff]+$/.test(cand)) continue;
      if (CLAUSE_STOP.has(cand)) break;
      /* 3 字被「實物結尾」擋掉（小飛機／老照片）就整個放棄，
         不要退成 2 字 —— 否則會收下「小飛」「鄭刑」這種半截名。 */
      if (!canBeBareName(cand)) { if (len === 3 && THING_TAIL.has(cand[2])) break; continue; }
      clause.set(cand, (clause.get(cand) || 0) + 1);
      break;
    }
  }
  /* 短篇 3 次、長篇 8 次（實測 9 千字短篇的主角在句首出現 20+ 次）。 */
  const clauseNeed = text.length < 3000 ? 3 : 8;
  for (const [n, c] of clause) {
    if (c >= clauseNeed) { cnt.set(n, Math.max(cnt.get(n) || 0, c)); loose.delete(n); }
  }
  /* 半截名全部丟掉：「鄭組」「張醫」「分局」（分局長的前綴）—— 這是
     「名字＋職稱」與句首統計兩條規則的副產品，每篇都會冒出幾個。
     一定要放在所有規則之後，否則後面的規則會把它們再加回來。 */
  const nameKeys = [...cnt.keys()];
  const longerWords = nameKeys.concat(ROLE_WORDS, NAME_TITLES, Array.from(FAMILY_WORDS));
  for (const n of nameKeys) {
    if (longerWords.some(function (m) { return m !== n && m.length > n.length && m.indexOf(n) === 0; })) cnt.delete(n);
  }

  /* 放寬規則進來的名字要用次數把關：只出現一兩次的多半是誤判。
     門檻跟職稱一致（短篇低、長篇高）。 */
  const looseNeed = text.length < 3000 ? 2 : 3;
  const names = [...cnt.entries()]
    .filter(([name, count]) => !loose.has(name) || count >= looseNeed)
    .map(([name, count]) => ({ name, count, role: '' }))
    .sort((a, b) => b.count - a.count);
  /* 職稱：出現 ≥3 次且沒被當成名字抓過，就當一個角色（偵探小說常寫「偵探說」）。 */
  const roles = [];
  /* 短篇的門檻要低一點：1,000 字的故事裡「合夥人」出現 2 次就是主要角色，
     用長篇的門檻（3 次）會整個漏掉。長篇維持 3 次避免雜訊。 */
  const need = text.length < 3000 ? 2 : 3;
  for (const w of ROLE_WORDS) {
    if (cnt.has(w)) continue;
    let c = 0, embedded = 0;
    for (let i = text.indexOf(w); i >= 0; i = text.indexOf(w, i + 1)) {
      c++;
      /* 「林刑警」裡的「刑警」：前面接姓氏且姓＋職業已是抓到的名字 → 算被包住 */
      if (i > 0 && SURNAMES.has(text[i - 1]) && cnt.has(text[i - 1] + w)) embedded++;
    }
    /* 獨立出現的次數要夠，才算一個角色；全被姓名包住就不要另立角色
       （實測：「刑警」搶走「林刑警」的鏡頭，林刑警反而 0 鏡） */
    if (c >= need && (c - embedded) >= need) roles.push({ name: w, count: c - embedded, role: w });
  }
  roles.sort((a, b) => b.count - a.count);
  return { persons: names.concat(roles).slice(0, limit), intro: [...intro] };
}

/* ---- 讀檔：一律先讀成 ArrayBuffer，再判斷編碼 ---- */
function decodeText(buf) {
  const u8 = new Uint8Array(buf);
  if (u8.length >= 3 && u8[0] === 0xEF && u8[1] === 0xBB && u8[2] === 0xBF)
    return { text: new TextDecoder('utf-8').decode(u8.subarray(3)), enc: 'UTF-8 (BOM)' };
  if (u8.length >= 2 && u8[0] === 0xFF && u8[1] === 0xFE)
    return { text: new TextDecoder('utf-16le').decode(u8), enc: 'UTF-16LE' };
  if (u8.length >= 2 && u8[0] === 0xFE && u8[1] === 0xFF)
    return { text: new TextDecoder('utf-16be').decode(u8), enc: 'UTF-16BE' };
  try { return { text: new TextDecoder('utf-8', { fatal: true }).decode(u8), enc: 'UTF-8' }; } catch (e) { }
  /* 不是合法 UTF-8 → 台灣常見的 Big5 與對岸的 GBK 之間選一個最像的。
     TextDecoder 對不支援的編碼會丟錯，一併跳過。 */
  let best = null, bestScore = -Infinity, bestEnc = '';
  for (const enc of ['big5', 'gbk', 'utf-8']) {
    let t;
    try { t = new TextDecoder(enc).decode(u8); } catch (e) { continue; }
    const bad = (t.match(/\uFFFD/g) || []).length;
    const cjk = (t.match(/[\u4e00-\u9fff]/g) || []).length;
    const score = cjk - bad * 20;
    if (score > bestScore) { bestScore = score; best = t; bestEnc = enc; }
  }
  return { text: best || '', enc: (bestEnc || '未知').toUpperCase() + '（自動判定）' };
}

/* .docx = ZIP，內含 word/document.xml。只解出這一個檔，其餘略過。 */
async function docxToXml(buf) {
  const u8 = new Uint8Array(buf), dv = new DataView(buf);
  let eocd = -1;
  const floor = Math.max(0, u8.length - 66000);
  for (let i = u8.length - 22; i >= floor; i--) {
    if (dv.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
  }
  if (eocd < 0) throw new Error('不是有效的 .docx（找不到 ZIP 結尾）');
  const count = dv.getUint16(eocd + 10, true);
  let off = dv.getUint32(eocd + 16, true);
  const dec = new TextDecoder('utf-8');
  let entry = null;
  for (let n = 0; n < count; n++) {
    if (dv.getUint32(off, true) !== 0x02014b50) break;
    const method = dv.getUint16(off + 10, true);
    const compSize = dv.getUint32(off + 20, true);
    const nameLen = dv.getUint16(off + 28, true);
    const extraLen = dv.getUint16(off + 30, true);
    const cmtLen = dv.getUint16(off + 32, true);
    const localOff = dv.getUint32(off + 42, true);
    const name = dec.decode(u8.subarray(off + 46, off + 46 + nameLen));
    if (name === 'word/document.xml') entry = { method, compSize, localOff };
    off += 46 + nameLen + extraLen + cmtLen;
  }
  if (!entry) throw new Error('不是有效的 .docx（缺少 word/document.xml）');
  const lhNameLen = dv.getUint16(entry.localOff + 26, true);
  const lhExtraLen = dv.getUint16(entry.localOff + 28, true);
  const start = entry.localOff + 30 + lhNameLen + lhExtraLen;
  const data = u8.subarray(start, start + entry.compSize);
  if (entry.method === 0) return dec.decode(data);
  if (entry.method !== 8) throw new Error('這個 .docx 的壓縮方式不支援（method=' + entry.method + '）');
  const stream = new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
  return await new Response(stream).text();
}

/* 從 WordprocessingML 抽純文字：段落換行、只取 w:t 的文字。 */
function docxXmlToText(xml) {
  const s = xml.replace(/<w:tab\b[^>]*\/?>/g, '\t').replace(/<w:br\b[^>]*\/?>/g, '\n');
  const paras = s.split(/<\/w:p>/);
  const out = [];
  for (const p of paras) {
    let line = '';
    const re = /<(?:\w+:)?t\b[^>]*>([\s\S]*?)<\/(?:\w+:)?t>/g;
    let m;
    while ((m = re.exec(p))) line += m[1];
    line = line.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
      .replace(/&apos;/g, "'").replace(/&amp;/g, '&');
    out.push(line);
  }
  return out.join('\n');
}

/* HTML → 純文字（保留段落換行）。用 DOMParser，不引入任何套件。 */
const BLOCK_TAGS = new Set(['p', 'div', 'li', 'h1', 'h2', 'h3', 'h4', 'h5', 'h6', 'blockquote', 'pre',
  'tr', 'section', 'article', 'header', 'footer', 'table', 'ul', 'ol', 'figure', 'figcaption']);
function htmlToText(html) {
  const doc = new DOMParser().parseFromString(html, 'text/html');
  doc.querySelectorAll('script,style,noscript,template,head,nav,aside').forEach(e => e.remove());
  const walk = node => {
    let s = '';
    for (const n of node.childNodes) {
      if (n.nodeType === 3) { s += n.nodeValue; continue; }
      if (n.nodeType !== 1) continue;
      const tag = n.tagName.toLowerCase();
      if (tag === 'br') { s += '\n'; continue; }
      const block = BLOCK_TAGS.has(tag);
      s += (block ? '\n' : '') + walk(n) + (block ? '\n' : '');
    }
    return s;
  };
  const body = doc.body || doc.documentElement;
  return body ? walk(body) : '';
}

/* 正規化：統一換行、去掉多餘空白、把分隔線與章節標題變成段落界線。 */
/* 硬換行接回：中文 txt 常在 30 字左右斷行，不接回去的話斷句會全錯。
   只在「這行結尾不是句末標點」且「兩邊都不是段落標記」時接起來。
   英文單字之間要補空白，中文直接接。 */
function joinWrapped(t) {
  const ENDER = /[。！？…」』：；、,;:]$/;
  const STARTER = /^\s*(第\s*[0-9一二三四五六七八九十百零〇]+\s*[章節回篇]|【|——|─|\d+[、.．]|[（(]\d+[)）]|[-*+]\s|#)/;
  const out = [];
  for (const ln of t.split('\n')) {
    const i = out.length - 1;
    const prev = i >= 0 ? out[i] : null;
    if (prev && ln.trim() && !ENDER.test(prev) && !STARTER.test(ln) && !STARTER.test(prev)) {
      const glue = /[A-Za-z0-9]$/.test(prev) && /^[A-Za-z0-9]/.test(ln.trim()) ? ' ' : '';
      out[i] = prev + glue + ln.trim();
    } else {
      out.push(ln);
    }
  }
  return out.join('\n');
}

function normalizeNovel(t) {
  return joinWrapped(t.replace(/\r\n?/g, '\n')
    .replace(/\uFEFF/g, '')
    .replace(/\u3000/g, ' ')
    .replace(/[ \t]+/g, ' '))
    .replace(/^\s*[-—=*_#~]{3,}\s*$/gm, '\n')
    .replace(/^\s*第\s*[0-9一二三四五六七八九十百零〇]+\s*[章節回篇]\s*.*$/gm, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

/* 斷句：只在「」『』外面切，避免把一句對白切兩半。
   英文句點也算句尾 —— 否則沒有中文標點的文字會被當成一整句，變成巨型鏡頭。 */
function splitSentences(t) {
  const out = [];
  let buf = '', depth = 0;
  for (let i = 0; i < t.length; i++) {
    const ch = t[i];
    if (ch === '「' || ch === '『') depth++;
    else if (ch === '」' || ch === '』') depth = Math.max(0, depth - 1);
    buf += ch;
    const isDot = ch === '.' && /^(\s|$)/.test(t.substr(i + 1, 1));
    if (depth === 0 && ('。！？!?…'.indexOf(ch) >= 0 || isDot || ch === '\n')) {
      if (buf.trim()) out.push(buf.trim());
      buf = '';
    }
  }
  if (buf.trim()) out.push(buf.trim());
  return out;
}

/* 單句過長（整段沒標點）時強制切開，否則會出現 40 秒的巨型鏡頭。 */
function hardSplit(chunk, max) {
  const out = [];
  let rest = chunk;
  /* 先用寬一點的窗口找標點：原本只在 max 字內找，找不到就直接從字中間切開，
     造成「帶了一個人回」／「來，並且告訴…」這種把詞切一半的字幕。
     多讓幾個字去換一個自然斷點，字幕讀起來才不會斷氣。 */
  const wide = Math.round(max * 1.6);
  while (rest.length > max) {
    let cut = -1;
    for (const p of ['，', '、', '；', '：', ',', ';', ' ']) {
      const i = rest.lastIndexOf(p, wide);
      if (i > cut && i >= Math.floor(max * 0.5)) cut = i + 1;
    }
    if (cut < 0) cut = max;
    out.push(rest.slice(0, cut));
    rest = rest.slice(cut);
  }
  if (rest) out.push(rest);
  return out;
}

/* 場景：地名詞庫 + 明示標記（場景：／【】）。 */
function extractPlaces(text, limit) {
  const cnt = new Map();
  const add = (n, c) => { if (n) cnt.set(n, (cnt.get(n) || 0) + (c || 1)); };
  for (const w of PLACE_ALL) {
    const c = (text.match(new RegExp(w, 'g')) || []).length;
    if (c > 0) add(w, c);
  }
  let m;
  const reScene = /場景\s*[：:]\s*([^\n，,。；;]{2,12})/g;
  while ((m = reScene.exec(text))) add(m[1].trim(), 99);
  const reBrk = /[【〖]([^】〗]{2,12})[】〗]/g;
  while ((m = reBrk.exec(text))) add(m[1].trim(), 50);
  return [...cnt.entries()].map(([name, count]) => ({ name, count, type: PLACE_TYPE[name] || '室外' }))
    .sort((a, b) => b.count - a.count).slice(0, limit);
}

/* 鏡頭景別判斷：由旁白內容推測，使用者再自己改。 */
const SIZE_RULES = [
  [/手指|手裡|手中|戒指|錶|門把|鑰匙|照片|信件|紙條|刀刃|血跡|檔案|手機|酒杯/, '物件'],
  [/眼神|眼中|眼睛|嘴角|眉毛|表情|臉|臉頰|嘴唇/, '特寫'],
  [/天空|遠方|遠處|整個|四周|全景|遠眺|望去|街|人群|全景|窗外/, '遠景'],
  [/走進|走出|走過|穿過|來到位於|步入/, '遠景']
];

function guessSize(chunk, isDialogue) {
  for (const [re, size] of SIZE_RULES) if (re.test(chunk)) return size;
  if (isDialogue) return '近景';
  return '中景';
}

const MOVE_CYCLE = ['固定', '緩慢左移', '緩慢右移', '輕微晃動'];

/* 第③段（鏡頭描述）種子：從旁白取一段具體畫面，使用者再手改成視覺描述。 */
function seedLens(chunk, size, move) {
  let s = chunk.replace(/^[「『]/, '').replace(/[」』]$/, '').replace(/\s+/g, '');
  const cuts = ['，', '。', '、', '；', '：'];
  for (const c of cuts) {
    const i = s.indexOf(c);
    if (i >= 8 && i <= 26) { s = s.slice(0, i); break; }
  }
  if (s.length > 30) s = s.slice(0, 30);
  return s;
}

/* ══════════════════════════════════════════════════════════════════
   判斷層：把旁白文字判斷成「畫面」
   目的：匯入小說後直接產出可用的第③段鏡頭描述，不必逐鏡手寫。
   全部規則式、零外部呼叫（維持單檔離線的硬性要求）。
   ══════════════════════════════════════════════════════════════════ */

/* ── 敘述者（第一人稱）──
   第一人稱小說用「我」敘述，主角名字可能只出現一兩次。
   不處理的話主角在鏡頭表裡幾乎全程缺席（實測 39/59 鏡無角色）。
   判斷順序：①「我叫X」句型 ②「我，X，」同位語 ③只認得出一個真人名 */
/* 這個位置是否在引號內（「…」或『…』）？引號裡是對白，不是敘述句。 */
function inQuote(text, at) {
  let d1 = 0, d2 = 0;
  for (let i = 0; i < at; i++) {
    const c = text[i];
    if (c === '「') d1++;
    else if (c === '」') d1 = Math.max(0, d1 - 1);
    else if (c === '『') d2++;
    else if (c === '』') d2 = Math.max(0, d2 - 1);
  }
  return d1 > 0 || d2 > 0;
}
function detectNarrator(text, persons, introNames) {
  /* 「我」只算引號外的：三人稱小說的「我」幾乎全在對白裡，算進來會讓
     三人稱作品被誤判成第一人稱 —— 實測《鋼針》的對白「瞧不起我石頭李」
     害石頭李變成敘述者，整篇角色卡跟著歪。 */
  let wo = 0;
  for (let i = text.indexOf('我'); i >= 0; i = text.indexOf('我', i + 1)) if (!inQuote(text, i)) wo++;
  if (wo < 3) return { name: '', firstPerson: false, wo: wo };
  for (const n of introNames) if (persons.some(p => p.name === n)) return { name: n, firstPerson: true, wo: wo };
  for (const p of persons) {
    const re = new RegExp('我[，、,]?\\s*' + p.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
    let m;
    while ((m = re.exec(text)) !== null) {
      if (!inQuote(text, m.index)) return { name: p.name, firstPerson: true, wo: wo };
    }
  }
  /* ③ 全篇只認得出一個「人名」→ 那就是敘述者。
     但要排除職業／親屬稱謂：實測「阿婆」（說了一句「是我發現的」）被當成敘述者，
     因為全篇只有它被抓成名字 —— 稱謂不是人名，不能當敘述者。 */
  const roleSet = new Set([].concat(ROLE_WORDS, Array.from(FAMILY_WORDS), NAME_TITLES));
  const real = persons.filter(p => !p.role && !roleSet.has(p.name));
  if (real.length === 1) return { name: real[0].name, firstPerson: true, wo: wo };
  return { name: '', firstPerson: true, wo: wo };   /* 有「我」但認不出是誰 */
}

/* ── 代名詞消解 ──
   「他／她」回指前文最近被點名的角色。小說是連續敘事，
   代名詞通常指向前面最近出現的人；她偏女性角色、他偏男性。 */
const FEMALE_WORDS = ['母親', '媽媽', '妻子', '太太', '女兒', '姊姊', '妹妹', '姐姐', '奶奶', '外婆',
  '女友', '情婦', '老闆娘', '護士', '學姊', '寡婦', '老婦', '少女', '女孩', '女人'];
const MALE_WORDS = ['父親', '爸爸', '丈夫', '兒子', '哥哥', '弟弟', '爺爺', '外公', '男友', '師父',
  '師傅', '探長', '警官', '警探', '刑警', '醫生', '律師', '檢察官', '法醫', '警衛', '船長', '男人', '老人'];

function genderOf(p) {
  if (FEMALE_WORDS.indexOf(p.name) >= 0) return 'f';
  if (MALE_WORDS.indexOf(p.name) >= 0) return 'm';
  return '';
}

/* 中文名字的性別傾向（看最後一個字）。只在沒有其他線索時當「提示」用 ——
   敘述者幾乎不會被「他」指涉到（他自己就是「我」），這條是最後一道。 */
const NAME_MALE_CHARS = '貴雄強明華國文武龍志建偉豪傑宏昌盛福財發信義德正宗良清山虎剛毅';
const NAME_FEMALE_CHARS = '美麗花芳娟淑惠玲珍貞妹女香玉珠琴娥嬌雯靜怡';
const KIN_F = '婆嬤媽姊妹姐姑姨嬸嫂娘婦', KIN_M = '公伯叔爺哥弟爸';
/* 稱謂字結尾 → 性別鐵定（阿婆＝女、阿公＝男）。真名不走這條。 */
function kinGender(name) {
  if (!name) return '';
  const c = name[name.length - 1];
  if (KIN_F.indexOf(c) >= 0) return 'f';
  if (KIN_M.indexOf(c) >= 0) return 'm';
  return '';
}

function nameGender(name) {
  if (!name || name.length < 2) return '';
  const c = name[name.length - 1];
  const kin = kinGender(name);
  if (kin) return kin;
  if (NAME_MALE_CHARS.indexOf(c) >= 0) return 'm';
  if (NAME_FEMALE_CHARS.indexOf(c) >= 0) return 'f';
  return '';
}

/* 用代名詞反推性別：文中出現「他」時，往前找最近被點名的角色，那就是男性；
   「她」同理是女性。角色詞以外的名字（林啟明、林小姐…）靠這條才判得出性別。 */
function inferGenders(text, persons) {
  const g = {};
  persons.forEach(function (p) { const x = genderOf(p); if (x) g[p.name] = x; });
  /* 稱謂結尾的性別最可信（阿婆／阿公），先鎖住，後面代名詞推斷不准覆蓋。
     只認「稱謂字結尾」——真名的性別還是要靠代名詞，不能一律鎖死。 */
  const locked = {};
  persons.forEach(function (p) {
    const x = genderOf(p) || kinGender(p.name);
    if (x) locked[p.name] = x;
  });
  /* 把稱謂性別先寫進結果，代名詞推斷就不會蓋掉（阿婆曾被判成男性） */
  persons.forEach(function (p) { if (locked[p.name] && !g[p.name]) g[p.name] = locked[p.name]; });
  /* 代名詞推斷：取「前面最近的名字」，視窗 20 字。
     視窗不能開太大 —— 40 字會把隔壁角色的代名詞黏過來（實測「張醫師」被判成
     女性，因為前一句的「她」指的是另一位女醫師）。實測 40／20／12 三種視窗，
     20 字最穩：該對的都對，判不出的寧可留空，也不要自信地猜錯。 */
  const re = /(?<!其)[他她]/g;
  let m;
  while ((m = re.exec(text)) !== null) {
    const k = m.index;
    let best = '', at = -1;
    for (const p of persons) {
      const q = text.lastIndexOf(p.name, k - 1);
      if (q > at && k - q <= 20) { at = q; best = p.name; }
    }
    if (best && !g[best]) g[best] = m[0] === '她' ? 'f' : 'm';
  }
  return g;
}

