function traitSubject(chunk, names) {
  for (const t of TRAIT_PHRASES) {
    const k = chunk.indexOf(t[0]);
    if (k < 0) continue;
    /* 取「離氣質詞最近」的名字，不是清單裡第一個命中的。
       「父親的合夥人看起來忠厚老實」——被形容的是合夥人，不是父親；
       父親雖然也在 8 字內，但距離比較遠。 */
    let best = '', bestGap = 9;
    for (const n of names) {
      const p = chunk.lastIndexOf(n, k - 1);
      if (p < 0) continue;
      const gap = k - (p + n.length);
      if (gap >= 0 && gap < bestGap) { bestGap = gap; best = n; }
    }
    if (best) return { name: best, phrase: t[1] };
  }
  return null;
}

