/* 身份 -> 固定服裝（資料驅動，比寫死的 regex 好維護） */

/* ── 造型建議（髮型／臉型／服裝／辨識記憶點）──
   小說通常不寫長相，但「留空」對使用者沒幫助，而且待補括號會混進 prompt。
   改成給具體建議：用「年代 × 性別 × 身份」挑，並用名字雜湊固定挑選結果
   ——同一個角色每次匯入都拿到同一組，不會這次長這樣、下次長那樣。 */

/* 古裝的「不可能誤判」證據：這些詞在現代文本裡幾乎不會出現。 */
const ERA_ANCIENT_CERTAIN = /衙門|縣衙|公堂|客棧|客官|師爺|銀兩|仵作|捕快|縣令|知縣|皇上|轎子|馬車|客倌/;
/* 弱證據：現代作品照樣會用 —— 「太爺」「大人」可以拿來開玩笑（實測分局長說
   「是縣太爺的老丈人啊」，整篇 1993 年的故事被判成古裝），「江湖」可以拿來
   比喻武俠小說。要數量壓過現代詞才採信。 */
const ERA_ANCIENT_WEAK = /太爺|大人|老爺|相公|長衫|辮子|江湖|馬匹|刀劍|銀兩/g;
/* 近代（日治〜民國初年）的證據。「騎樓」「民國」不能算 ——
   騎樓在今天的台灣到處都是，「民國八十二年」代表的是現代（實測兩次誤判，
   1993 年的故事被套上人力車與紅磚洋樓）。 */
const ERA_NEAR = /旗袍|中山裝|留聲機|洋行|學堂|人力車|三輪車|電報|日治|昭和|洋裝|鴉片|煙斗/;
/* 「大人」「老爺」是弱證據 —— 現代故事照樣會出現（實測：1992 年的故事裡
   女經理說「哦，是警官大人」，整篇就被判成古裝，場景全變成宣紙與太師椅）。
   弱證據要多到壓過現代詞才採信。 */
const ERA_MODERN_MARK = /電話|汽車|警察|警車|驗屍|法醫|賓館|旅館|無線電|保險|機車|摩托車|報紙|電視|冷氣|冰箱|分局|檢察官|身分證/g;
function detectEra(text) {
  const modern = (text.match(ERA_MODERN_MARK) || []).length;
  if (ERA_ANCIENT_CERTAIN.test(text)) return '古裝';
  const near = (text.match(ERA_NEAR) || []).length;
  /* 近代證據要夠多，或完全沒有現代詞（只有一句「日治時代」帶過的不算） */
  if (near >= 2 || (near >= 1 && modern === 0)) return '近代';
  const weak = (text.match(ERA_ANCIENT_WEAK) || []).length;
  if (weak >= 3 && weak > modern) return '古裝';
  return '現代';
}

