/* 名字雜湊：同一角色固定拿到同一組建議 */
function nameHash(s) {
  /* FNV-1a：短名字用 (h*31+c)%99991 容易撞同一組建議（實測三個角色拿到同一組眼神） */
  let h = 2166136261;
  for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619) >>> 0; }
  /* 必須再做一次雪崩混合：中文兩字名在 FNV 的低位有偏誤，
     實測 mod 6 全部落在同一個值（四個角色拿到同一種臉型）。 */
  h ^= h >>> 15; h = Math.imul(h, 2246822507) >>> 0;
  h ^= h >>> 13; h = Math.imul(h, 3266489909) >>> 0;
  h ^= h >>> 16;
  return h >>> 0;
}
/* 池子小時單靠雜湊很容易撞（實測古裝 4 個角色拿到同一套服裝）。
   加「角色序號」錯開：同一篇裡每個角色的建議一定不同。 */
function pickOne(list, seed, salt, rank) {
  return list[(nameHash(seed + '#' + salt) + (rank || 0)) % list.length];
}
/* 同篇不重複 —— 辨識記憶點的用途就是「分得出是誰」，
   兩個角色掛同一只玉墜就等於沒有記憶點。 */
function pickUnique(list, seed, salt, rank, taken) {
  let idx = (nameHash(seed + '#' + salt) + (rank || 0)) % list.length;
  if (taken) {
    for (let k = 0; k < list.length && taken.has(list[idx]); k++) idx = (idx + 1) % list.length;
    taken.add(list[idx]);
  }
  return list[idx];
}

/* 文中有明寫的長相就直接用（「戴著眼鏡」「長衫」「光頭」…） */
const APPEARANCE_HINTS = [
  [/戴[著了]?[一]?副眼鏡|細框眼鏡|金邊眼鏡/, '戴一副眼鏡'],
  [/長衫/, '穿著長衫'], [/西裝/, '穿著西裝'], [/風衣/, '穿著風衣'],
  [/旗袍/, '穿著旗袍'], [/制服/, '穿著制服'], [/圍裙/, '腰間繫著圍裙'],
  [/白髮|銀髮/, '滿頭白髮'], [/禿/, '髮量稀疏'], [/鬍|鬚/, '蓄著鬍鬚'],
  [/疤/, '臉上有一道疤'], [/辮子/, '蓄著辮子'], [/草帽|斗笠/, '戴著帽子'],
  [/酒臭|酒味/, '身上帶著酒氣'], [/瘦/, '身形瘦削'], [/魁梧|壯/, '身形魁梧']
];
function appearanceHints(text, name) {
  /* 只看「名字所在的子句」。用固定字數窗（±40）會跨到別人的句子——
     實測「父親渾身散發酒臭味」的酒氣被算到母親身上。 */
  const marks = '。！？，、；：\n「」『』（）';
  const clauses = [];
  for (let k = text.indexOf(name); k >= 0; k = text.indexOf(name, k + 1)) {
    let a = k, b = k + name.length;
    while (a > 0 && marks.indexOf(text[a - 1]) < 0) a--;
    while (b < text.length && marks.indexOf(text[b]) < 0) b++;
    clauses.push(text.slice(a, b));
  }
  const joined = clauses.join('｜');
  const out = [];
  for (const h of APPEARANCE_HINTS) if (h[0].test(joined)) out.push(h[1]);
  return out;
}

function suggestLook(p, text, ctx) {
  const era = ctx.era;
  const g = (ctx.gender === 'f') ? 'f' : 'm';
  const hintText = appearanceHints(text, p.name).join('，');
  const rk = ctx.rank || 0;
  const tk = ctx.taken || {};
  const hair = pickUnique(HAIR[era][g], p.name, 'hair', rk, tk.hair);
  const face = pickUnique(FACE_SHAPES, p.name, 'face', rk, tk.face);
  const eyes = pickOne(EYES, p.name, 'eyes', rk * 2);
  const markPool = MARK_POOL.filter(function (m) {
    return (m[1] === 'n' || m[1] === g) && eraOK(m[0], era);
  }).map(function (m) { return m[0]; });
  const mark = pickUnique(markPool, p.name, 'mark', rk * 5, tk.mark);
  const cand = ctx.outfitPick ? ctx.outfitPick(p, g) : null;
  const outfit = pickUnique(cand || OUTFITS[era][g], p.name, 'out', rk, tk.out);
  return { hair: hair, face: face, eyes: eyes, outfit: outfit, mark: mark, hints: hintText };
}

/* ── ①人物描述草稿 ──
   小說不會描述長相。能從文字推出來的是身份／年齡／氣質，
   長相一律留成明確的待補欄位 —— 不亂編，編錯了會鎖錯臉。 */
function contextsOf(text, word, span) {
  const out = [];
  for (let k = text.indexOf(word); k >= 0 && out.length < 6; k = text.indexOf(word, k + 1)) {
    out.push(text.slice(Math.max(0, k - span), Math.min(text.length, k + word.length + span)));
  }
  return out.join('｜');
}

function draftPersonDesc(p, text, narrator, genders, era, styleName, rank, taken) {
  const g = (genders && genders[p.name]) || genderOf(p) || nameGender(p.name);
  const near = contextsOf(text, p.name, 12);
  const age = ['老年', '中年', '年輕', '少年', '少女'].find(function (k) { return near.indexOf(k) >= 0; });
  let job = '';
  /* ① 名字本身帶著職業（「張醫生」「林刑警」）→ 直接用，不要模糊搜尋
     （實測：張醫生被判成「警察」，只因「警察」剛好出現在 ±12 字內） */
  const tailRoles = ROLE_WORDS.filter(function (w) {
    return w.length >= 2 && p.name.length > w.length && p.name.slice(-w.length) === w;
  }).sort(function (a, b) { return b.length - a.length; });
  if (tailRoles.length) job = tailRoles[0];
  /* ② 名字正後方緊接著的職業詞 */
  if (!job) {
    const i0 = text.indexOf(p.name);
    if (i0 >= 0) for (const w of ROLE_WORDS) {
      if (w === p.name || FAMILY_WORDS.has(w)) continue;
      if (text.slice(i0 + p.name.length, i0 + p.name.length + w.length) === w) { job = w; break; }
    }
  }
  /* ③ 最後手段：附近出現過的職業詞 */
  if (!job) job = ROLE_WORDS.find(function (w) {
    return w !== p.name && !FAMILY_WORDS.has(w) && near.indexOf(w) >= 0;
  }) || '';
  /* 身份／題材決定服裝：探長配風衣、長輩配圍裙、黑色電影配風衣 */
  const outfitPick = function (pp) {
    const n = pp.name;
    /* ① 身份資料表優先（69 條，涵蓋古裝到科幻），只取符合年代的候選 */
    if (typeof ROLE_OUTFIT_HINTS !== 'undefined') {
      for (const h of ROLE_OUTFIT_HINTS) {
        if (h[0].test(n)) {
          const ok = h[1].filter(function (x) { return eraOK(x, era); });
          if (ok.length) return ok;
        }
      }
    }
    if (era === '古裝') return '';        /* 古裝角色一律用年代服裝池 */
    if (/探長|警官|警探|刑警|警察|偵探|法醫|檢察官/.test(n))
      return ['深色風衣內搭白襯衫，領口略鬆', '深色外套與長褲，胸前口袋插著一支筆'];
    if (/母親|媽媽|奶奶|外婆|妻子|太太|姊姊|妹妹|女兒/.test(n))
      return ['樸素的深色洋裝，袖子挽到手肘，腰間繫著圍裙',
        '素色長袖上衣與長裙，布料洗得柔軟'];
    if (/父親|爸爸|爺爺|外公|丈夫|哥哥|弟弟|兒子/.test(n))
      return ['深色襯衫配西裝褲，腰上皮帶扣明顯', '深色夾克內搭襯衫，衣著樸素整潔'];
    if (/學生|少年|少女|徒弟/.test(n))
      return ['白襯衫配深色長褲，肩上一只舊書包'];
    /* 古裝題材就算被判成 noir，也不能給風衣 —— 年代優先於題材 */
    if (era !== '古裝' && styleName === '黑色電影')
      return ['深灰風衣內搭白襯衫，領口略鬆', '深色大衣配長褲，圍著一條舊圍巾'];
    return null;
  };
  const look = suggestLook(p, text, { era: era, gender: g, outfitPick: outfitPick, rank: rank, taken: taken });

  /* 性別判不出來就整格省略 —— 「人物」這兩個字進了 prompt 只是雜訊 */
  const head = [];
  if (g === 'f') head.push('女性');
  else if (g === 'm') head.push('男性');
  if (age) head.push(age);
  if (p.role) head.push(p.role);
  else if (job) head.push(job);
  else if (narrator && narrator.name === p.name) head.push('第一人稱敘述者');

  const parts = [head.join('，')];
  if (look.hints) parts.push(look.hints);              /* 文中明寫的長相優先 */
  parts.push([look.hair, look.face, look.eyes].join('，'));
  parts.push(look.outfit);
  parts.push(look.mark);
  return parts.filter(function (x) { return x && x.trim(); }).join('；');
}

