/* 季節：文中明寫就用文的，沒寫就整篇挑一個固定值（不要每場換季） */
function detectSeason(text) {
  /* 整篇一起算、取分數最高的季節。原本只看前 600 字，還把單一個「秋」字
     當證據，實測一篇「盛暑・八月二十日」的夏日故事被判成秋天。 */
  const score = { 冬: 0, 春: 0, 夏: 0, 秋: 0 };
  const add = (re, k, w) => { score[k] += (text.match(re) || []).length * w; };
  add(/雪|冬天|寒冷|寒風|寒流|冷得發抖|棉被/g, '冬', 2);
  add(/春天|春雨|花開|萌芽|新綠/g, '春', 2);
  add(/夏天|夏日|盛夏|盛暑|暑期|酷暑|炎夏|炎熱|酷熱|蟬鳴|蟬聲|熱得/g, '夏', 2);
  add(/秋天|秋日|秋風|落葉|楓紅/g, '秋', 2);
  /* 月份（台灣：6-8 月夏、9-11 月秋、3-5 月春、12-2 月冬） */
  add(/六月|七月|八月/g, '夏', 1);
  add(/九月|十月|十一月/g, '秋', 1);
  add(/三月|四月|五月/g, '春', 1);
  add(/十二月|一月|二月/g, '冬', 1);
  const best = ['冬', '春', '夏', '秋'].sort((a, b) => score[b] - score[a])[0];
  if (!score[best]) return '';
  return { 冬: '冬天，濕冷', 春: '春天，地面微濕', 夏: '夏天，空氣悶熱', 秋: '秋天，落葉堆在角落' }[best];
}

function draftSceneDesc(pl, text, era, rank, ctx) {
  const type = pl.type === '室內' ? '室內' : '室外';
  const rk = rank || 0;
  let tex = '';
  for (const r of PLACE_TEX_BY_NAME) {
    if (!r[0].test(pl.name)) continue;
    /* 場所樣式也要過年代濾網 —— 先前這條路徑完全沒過濾，古裝材質（紙窗、宣紙、
       太師椅）就這樣流進現代場景。全被濾掉時才退回未過濾的清單。 */
    const cand = r[1].filter(function (x) { return eraOK(x, era); });
    tex = pickOne(cand.length ? cand : r[1], pl.name, 'name', rk);
    break;
  }
  if (!tex) {
    const all = SCENE_TEXTURE[type][era] || SCENE_TEXTURE[type]['現代'];
    let pool = all.filter(function (x) { return eraOK(x, era) && !PLACE_SPECIFIC.test(x); });
    if (!pool.length) pool = all.filter(function (x) { return eraOK(x, era); });
    if (!pool.length) pool = all;
    tex = pickOne(pool, pl.name, 'tex', rk);
  }
  const c = ctx || {};
  let lights = SCENE_LIGHT[type].filter(function (x) { return eraOK(x, era); });
  if (PLACE_NATURE.test(pl.name)) lights = lights.filter(function (x) { return !LIGHT_URBAN.test(x); });
  if (!lights.length) lights = SCENE_LIGHT[type];
  const light = pickOne(lights, pl.name, 'slight', rk);
  /* 季節整篇一致（同一部作品的視覺要統一），由 analyzeNovel 決定後傳進來 */
  const sPool = SCENE_SEASON.filter(function (x) { return eraOK(x, era); });
  const season = (c.season && eraOK(c.season, era))
    ? c.season
    : sPool[nameHash(pl.name + '#ssn') % (sPool.length || 1)];
  return pl.name + '：' + tex + '；' + light + '；' + season;
}

/* ── 主判斷：這一段畫面裡「誰、在做什麼、什麼光」→ 第③段 ── */
function visualize(chunk, ctx) {
  const size = ctx.size || '中景';
  const hit = function (list) { return list.find(function (x) { return chunk.indexOf(x[0]) >= 0; }); };
  const face = hit(FACE_PHRASES);
  const acts = ACTION_PHRASES.filter(function (x) { return chunk.indexOf(x[0]) >= 0; }).slice(0, 2);
  const light = hit(LIGHT_PHRASES);
  const obj = hit(OBJ_CLOSEUP);   /* 配對陣列：x[0] 是關鍵詞、x[1] 是畫面文字 */
  const noun = hit(NOUN_VISUALS);
  const trait = ctx.trait || traitSubject(chunk, ctx.names || []);
  const jump = hit(TIME_JUMP);
  const addr = ADDRESS_RE.test(chunk);
  const crowd = /大家|眾人|兩人|一群人|所有人|他們/.test(chunk);
  const place = ctx.places.filter(function (p) { return chunk.indexOf(p.name) >= 0; })[0];
  const parts = [];

  /* ①主體：只寫畫面看得到的（whoFrom 是給介面看的判斷依據，不進 prompt） */
  const subject = trait ? trait.name : ctx.who;
  if (subject) {
    let s = subject;
    if (trait) s += '，' + trait.phrase;
    else if (face) s += '，' + face[1];
    if (acts.length) s += '，' + acts.map(function (a) { return a[1]; }).join('、');
    else if (crowd) s += '，與旁人同框的群像';
    else if (!face) s += '，' + size + '反應鏡頭';
    parts.push(s);
  }
  if (place) parts.push(place.name + '：' + (PLACE_FLAVOR[place.type] || '環境交代'));
  if (obj) parts.push((obj[1] || (obj[0] + '特寫')) + '，清楚可辨');
  else if (noun && !ctx.who) parts.push(noun[1] + '（插入鏡）');
  if (light) parts.push(light[1]);
  if (jump) parts.push(jump[1]);
  if (addr) parts.push('（對讀者說話）直視鏡頭');

  if (!parts.length) {
    /* 真的沒有可視線索（純抽象敘述）—— 誠實給建議，不要硬掰出畫面 */
    return '（敘述句，無明確動作）建議用' + size + '空景，或延續上一鏡畫面';
  }
  let out = parts.join('；');
  if (out.length > 80) out = out.slice(0, 80);
  return out;
}

/* 主分析：文字 → { persons, places, shots, stats } */
function analyzeNovel(rawText, opt) {
  const text = normalizeNovel(rawText);
  const wpm = num(S.meta.wpm, 260) || 260;
  const secPerShot = opt.secPerShot, target = Math.max(8, Math.round(wpm / 60 * secPerShot));
  const personPack = extractPersons(text, opt.maxChars);
  const persons = personPack.persons;
  /* 第一人稱：主角可能只在「我叫X」出現一次，後面全是「我」 */
  const narrator = detectNarrator(text, persons, personPack.intro);
  const genders = inferGenders(text, persons);
  const era = detectEra(text);
  /* 沒有現代科技詞 → 不要出現手機／電腦（老小說的年份常判不出來） */
  NO_MODERN_PROP = !MODERN_MARKERS.test(text);
  /* 造型的辨識欄位同篇不重複（重複就失去辨識功能） */
  const taken = { hair: new Set(), face: new Set(), mark: new Set(), out: new Set() };
  /* 季節整篇一致（一部作品不會每場換季）：文中明寫就用文的，否則用整篇雜湊挑一個固定值 */
  const season = detectSeason(text) || (function () {
    const pool = SCENE_SEASON.filter(function (x) { return eraOK(x, era); });
    return pool[nameHash(text.slice(0, 200)) % (pool.length || 1)] || '';
  })();

  const places = extractPlaces(text, opt.maxScenes);

  const sents = splitSentences(text);
  /* 合併句子成鏡頭：到達目標字數就切 */
  const merged = [];
  let buf = '';
  for (const s of sents) {
    if (!buf) { buf = s; continue; }
    if (buf.length >= target * 0.7) { merged.push(buf); buf = s; continue; }
    if ((buf + s).length > target * 2 && buf.length >= target * 0.5) { merged.push(buf); buf = s; continue; }
    buf += s;
  }
  if (buf.trim()) merged.push(buf);
  /* 沒有標點的長段落再強制切開，確保每鏡時長合理 */
  const chunks = [];
  for (const m of merged) {
    for (const p of (m.length > target * 1.8 ? hardSplit(m, target) : [m])) {
      /* 純標點的碎片（切句留下的「。」）不該變成一個鏡頭 */
      if (p.trim() && /[\u4e00-\u9fffA-Za-z0-9]/.test(p)) chunks.push(p.trim());
    }
  }

  /* 比對用的角色名要含 role 型角色（父親／母親／探長…），否則整篇沒有一個
     「某某說道」時，逐鏡角色會全空。順序沿用 persons（真名在前、角色在後），
     讓同一段同時出現真名與角色時，優先命中真名。 */
  const nameRe = persons.map(p => p.name);
  const shots = [];
  /* 場景起點留空，不猜。原本初始化成 places[0]（出現次數最高的場景），
     結果「臥室」在故事中段才出現，前面幾十個鏡頭卻全被標成臥室。
     角色的規則是不猜（猜錯會鎖錯臉），場景同理：沒提到就留空。 */
  let curScene = '';
  let lastName = '';   /* 前文最後被點名的角色，給「他／她」回指 */
  chunks.forEach((chunk, i) => {
    const isDialogue = chunk.indexOf('「') >= 0 || chunk.indexOf('『') >= 0;
    /* 場景：這一段提到哪個場景就切過去 */
    let hitScene = '';
    for (const p of places) if (chunk.indexOf(p.name) >= 0) { hitScene = p.name; break; }
    if (hitScene) curScene = hitScene;   /* 場景一旦出現就一直沿用到下一個場景 */

    /* ── 角色判斷（愈前面愈優先）──
       ① 明確點名：這一段最多、且不是「X的合夥人」這種修飾用法
       ② 「我」＝敘述者：第一人稱小說的主角，不處理就全程缺席
       ③ 「他／她」＝前文最近點名的角色（代名詞回指）
       都判斷不出來才留空 —— 留空是安全的，猜錯會鎖錯臉。 */
    const trait = traitSubject(chunk, nameRe);
    const named = subjectName(chunk, nameRe);
    const woAt = chunk.search(/(?<!其)我/);          /* 「其他」不算 */
    const nameAt = named ? chunk.indexOf(named) : -1;
    let who = '', whoFrom = '';
    /* 氣質詞直接黏在某個名字後面（「合夥人看起來忠厚老實」）＝最強證據，
       比「這一段出現最多次」更可靠，優先採用。 */
    if (trait) { who = trait.name; whoFrom = '氣質詞'; }
    else if (named && (woAt < 0 || (nameAt >= 0 && nameAt <= woAt))) { who = named; whoFrom = '點名'; }
    else if (woAt >= 0 && narrator.name) { who = narrator.name; whoFrom = '我＝敘述者'; }
    else if (named) { who = named; whoFrom = '點名'; }
    else if (/(?<!其)[他她]/.test(chunk) && lastName) {
      /* 用「他」還是「她」決定性別期望；性別對不上就不要硬套
         （原本寫成「她出現且他沒出現才要 f」，導致「他」完全不受性別檢查，
          「母親」就被當成「他」所指的人）。 */
      const hasF = chunk.indexOf('她') >= 0, hasM = /(?<!其)他/.test(chunk);
      const want = (hasF && !hasM) ? 'f' : (hasM && !hasF ? 'm' : '');
      const cand = persons.filter(p => p.name === lastName)[0];
      const g = (genders && genders[lastName]) || (cand ? genderOf(cand) : '');
      if (!want || !g || want === g) { who = lastName; whoFrom = '代名詞'; }
    }
    /* 更新回指對象：這一段最後點名的人 */
    const mention = lastMentioned(chunk, nameRe);
    if (mention) lastName = mention;
    const size = guessSize(chunk, isDialogue);
    const prevScene = i > 0 ? shots[shots.length - 1]._scene : '';
    let move;
    if (i === 0 || (prevScene && prevScene !== curScene)) move = '緩慢推近';
    else if (isDialogue) move = '固定';
    else if (i < chunks.length - 1 && places.some(p => chunks[i + 1].indexOf(p.name) >= 0)) move = '緩慢拉遠';
    else move = MOVE_CYCLE[i % MOVE_CYCLE.length];
    const chars = chunk.replace(/\s/g, '').length;
    /* 秒數上限原本硬寫 8 秒，但介面允許設到 10 秒 ——
       設 8 秒以上時單鏡秒數被壓在 8，估時會低估 21~29%，單元數跟著算錯。
       改成尊重使用者的設定（至少 8 秒的彈性）。 */
    const durCap = Math.max(8, secPerShot * 1.5);
    const dur = Math.min(durCap, Math.max(2, Math.round(chars / wpm * 60 * 10) / 10));
    shots.push({
      narr: chunk, size, move, dur,
      lens: visualize(chunk, { who: who, whoFrom: whoFrom, size: size, places: places, names: nameRe, trait: trait }),
      _who: who, _whoFrom: whoFrom, _scene: curScene, _chars: chars
    });
  });

  const totalChars = shots.reduce((a, s) => a + s._chars, 0);
  const totalDur = shots.reduce((a, s) => a + s.dur, 0);
  return {
    persons: persons.map(function (p, i) {
      p.descDraft = draftPersonDesc(p, text, narrator, genders, era,
        guessStyle(text, opt.style), i, taken); return p;
    }),
    places: places.map(function (p, i) {
      p.descDraft = draftSceneDesc(p, text, era, i, { season: season }); return p;
    }),
    shots, wpm, secPerShot, narrator,
    stats: {
      chars: text.length, shots: shots.length, totalChars,
      totalDur, charsPerMin: wpm,
      units: Math.max(1, Math.ceil(totalDur / 900)),
      minutes: Math.round(totalDur / 60 * 10) / 10
    }
  };
}

/* 依偵測到的題材挑畫風；沒有強烈訊號就用寫實電影感（DEF_STYLE）。 */
function guessStyle(text, chosen) {
  if (chosen && STYLE_PRESETS[chosen]) return chosen;
  /* 比「命中次數」，不是比規則順序。原本誰先命中就贏，導致一句「我讀完高中」
     就能把復仇推理片判成日系動畫。 */
  const score = new Map();
  for (const [re, name] of GENRE_RULES) {
    const m = text.match(new RegExp(re.source, 'g'));
    if (m) score.set(name, (score.get(name) || 0) + m.length);
  }
  let best = '', bestN = 0;
  for (const [name, c] of score) if (c > bestN) { bestN = c; best = name; }
  return best || '寫實電影感';
}
